# name: math_category_match_contrast
# description: For sets of >=2 examples that all belong to a mathematical category the model does not represent (perfect squares, powers of two, cubes, primes), yes-rate on targets inside that category minus yes-rate on targets outside it; observed > null means people use these categories and the model under-produces category-based generalization.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    sq = {i * i for i in range(1, 11)}
    p2 = {2 ** i for i in range(0, 7)}
    cu = {i ** 3 for i in range(1, 5)}
    pr = {n for n in range(2, 101) if all(n % d for d in range(2, int(n ** 0.5) + 1))}
    cats = [sq, p2, cu, pr]
    inn, out = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) < 2:
            continue
        hit = [c for c in cats if all(x in c for x in ex)]
        if not hit:
            continue
        (inn if any(t in c for c in hit) else out).append(r)
    if not inn or not out:
        return 0.0
    return float(np.mean(inn) - np.mean(out))
EOF
cat << 'EOF' > same_decade_near_contrast.py
# name: same_decade_near_contrast
# description: Among targets outside the example set lying within 1-10 of their nearest example, yes-rate when the target shares that example's tens decade minus when it does not; observed > null means people use decade membership (which the model, with only size and final digit, lacks) and the model under-produces this contrast.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    same, diff = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if t in ex:
            continue
        x = min(ex, key=lambda e: abs(e - t))
        if abs(x - t) > 10:
            continue
        (same if min(x, 99) // 10 == min(t, 99) // 10 else diff).append(r)
    if not same or not diff:
        return 0.0
    return float(np.mean(same) - np.mean(diff))
EOF
cat << 'EOF' > sample_size_breadth_contrast.py
# name: sample_size_breadth_contrast
# description: Among targets outside the examples' span by 5-40, yes-rate for four-example sets minus yes-rate for one-example sets; observed < null means people narrow generalization with more examples (size principle) more than the model does, observed > null the reverse.
def test_statistic(df):
    k = df["number_set"].astype(str).str.count(",") + 1
    ex = df["number_set"].astype(str).str.split(",")
    mn = ex.map(lambda e: min(int(x) for x in e))
    mx = ex.map(lambda e: max(int(x) for x in e))
    t = df["target"].astype(int)
    gap = np.maximum(np.maximum(mn - t, t - mx), 0)
    sel = (gap >= 5) & (gap <= 40)
    r = df["rating"].astype(float)
    a = r[sel & (k == 4)]
    b = r[sel & (k == 1)]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())
EOF
