# name: exact_example_target_yes
# description: Yes-rate on trials whose target is one of the shown examples, minus yes-rate on targets within 1-3 of the nearest example; observed > null means people treat a repeated example as near-certainly produced far more than nearby numbers, and the model under-produces this boost.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    hit, near = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        d = min(abs(e - t) for e in ex)
        if d == 0:
            hit.append(r)
        elif d <= 3:
            near.append(r)
    if not hit or not near:
        return 0.0
    return float(np.mean(hit) - np.mean(near))
EOF
cat << 'EOF' > small_vs_large_region_gap.py
# name: small_vs_large_region_gap
# description: Among targets outside the span by a linear gap of 5-40, yes-rate when the nearest example is <=20 minus when the nearest example is >=60; observed < null means people compress large numbers (log-like magnitude) so equal linear gaps matter more among small numbers, which the linear-distance model fails to produce.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    small, large = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        gap = max(min(ex) - t, t - max(ex), 0)
        if gap < 5 or gap > 40:
            continue
        x = min(ex, key=lambda e: abs(e - t))
        if x <= 20:
            small.append(r)
        elif x >= 60:
            large.append(r)
    if not small or not large:
        return 0.0
    return float(np.mean(small) - np.mean(large))
EOF
cat << 'EOF' > first_vs_last_example_proximity.py
# name: first_vs_last_example_proximity
# description: In sets of >=2 examples, among non-example targets within 1-10 of their nearest example, yes-rate when that nearest example was shown first minus when it was shown last; observed > null means people weight the first example (primacy) more than the model's recency-weighted memory allows, observed < null means recency is stronger than modelled.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    first, last = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) < 2 or t in ex:
            continue
        d = [abs(e - t) for e in ex]
        i = int(np.argmin(d))
        if d[i] > 10:
            continue
        if i == 0:
            first.append(r)
        elif i == len(ex) - 1:
            last.append(r)
    if not first or not last:
        return 0.0
    return float(np.mean(first) - np.mean(last))
EOF
cat << 'EOF' > parity_violation_contrast.py
# name: parity_violation_contrast
# description: For sets of >=2 examples that all share one parity, yes-rate on opposite-parity targets minus same-parity targets; observed < null means people reject parity-violating targets more strongly than the model's graded parity similarity produces (observed > null: model over-penalizes parity).
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",")
    k = ex.str.len()
    odd = ex.map(lambda e: sum(int(x) % 2 for x in e))
    allsame = (k >= 2) & ((odd == 0) | (odd == k))
    setpar = (odd == k).astype(int)
    t = df["target"].astype(int)
    viol = (t % 2) != setpar
    r = df["rating"].astype(float)
    a = r[allsame & viol]
    b = r[allsame & ~viol]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())
EOF
